<script setup lang="ts">
import { router } from '@inertiajs/vue3'; import { Package, Pencil, Plus, Search } from 'lucide-vue-next'; import { computed, ref } from 'vue'; import { useI18n } from 'vue-i18n';
import Badge from '@/Core/Components/Badge.vue'; import Button from '@/Core/Components/Button.vue'; import Card from '@/Core/Components/Card.vue'; import DataTable, { type Column } from '@/Core/Components/DataTable.vue'; import EmptyState from '@/Core/Components/EmptyState.vue'; import Input from '@/Core/Components/Input.vue'; import PageHeader from '@/Core/Components/PageHeader.vue'; import Pagination from '@/Core/Components/Pagination.vue'; import Select from '@/Core/Components/Select.vue';
import { useAccess } from '@/Core/composables/useAccess'; import { useFormat } from '@/Core/composables/useFormat'; import TenantLayout from '@/Core/Layouts/TenantLayout.vue'; import { route } from '@/Core/lib/route'; import SalesNav from '../../../Components/SalesNav.vue'; import ProductFormDialog from '../../../Components/ProductFormDialog.vue'; import type { CatalogItemType, Product } from '../../../Components/types'; import type { Paginated } from '@/Core/types';
defineOptions({ layout: TenantLayout }); const props = defineProps<{ products: Paginated<Product>; filters: { search: string; type: CatalogItemType | null; active: boolean | null }; types: CatalogItemType[] }>(); const { t } = useI18n(); const { can } = useAccess(); const format = useFormat(); const manage = computed(() => can('crm.products.manage')); const formOpen = ref(false); const target = ref<Product | null>(null); const loading = ref(false); const search = ref(props.filters.search); const type = ref(props.filters.type ?? ''); const active = ref(props.filters.active === null ? '' : props.filters.active ? '1' : '0');
const typeOptions = computed(() => [{ value: '', label: t('crm.common.all') }, ...props.types.map((value) => ({ value, label: t(`crm.itemTypes.${value}`) }))]); const activeOptions = computed(() => [{ value: '', label: t('crm.common.all') }, { value: '1', label: t('crm.status.active') }, { value: '0', label: t('crm.sales.catalogue.inactive') }]); const columns = computed<Column[]>(() => [{ key: 'name', label: t('crm.fields.name') }, { key: 'type', label: t('crm.fields.type') }, { key: 'sku', label: t('crm.fields.sku'), hideable: true }, { key: 'price', label: t('crm.fields.unitPrice'), align: 'right' }, { key: 'active', label: t('crm.fields.status') }, { key: 'actions', label: t('crm.common.actions'), srOnly: true, align: 'right' }]);
function apply(): void { router.get(route('crm.sales.products.index'), { search: search.value || undefined, type: type.value || undefined, active: active.value === '' ? undefined : active.value }, { preserveState: true, replace: true, onStart: () => { loading.value = true; }, onFinish: () => { loading.value = false; } }); } function edit(item: Product | null): void { target.value = item; formOpen.value = true; }
</script>
<template><PageHeader :eyebrow="t('crm.eyebrow')" :title="t('crm.sales.catalogue.title')" :description="t('crm.sales.catalogue.description')"><template v-if="manage" #actions><Button variant="primary" @click="edit(null)"><template #icon><Plus class="size-4" aria-hidden="true" /></template>{{ t('crm.sales.catalogue.add') }}</Button></template></PageHeader><SalesNav current="products" /><Card flush><DataTable :columns="columns" :rows="products.data" row-key="id" :caption="t('crm.sales.catalogue.title')" :loading="loading" storage-key="crm-products"><template #toolbar><form class="flex min-w-0 flex-1 flex-wrap items-end gap-2" @submit.prevent="apply"><Input v-model="search" :label="t('crm.sales.catalogue.search')" class="min-w-48 flex-1" type="search"><template #leading><Search class="size-4" aria-hidden="true" /></template></Input><Select v-model="type" :options="typeOptions" :label="t('crm.fields.type')" class="w-full sm:w-36" /><Select v-model="active" :options="activeOptions" :label="t('crm.fields.status')" class="w-full sm:w-36" /><Button type="submit" size="sm">{{ t('crm.common.search') }}</Button></form></template><template #cell-name="{ row }"><div><p class="font-medium text-ink">{{ row.name }}</p><p v-if="row.description" class="max-w-80 truncate text-xs text-ink-subtle">{{ row.description }}</p></div></template><template #cell-type="{ row }"><Badge>{{ t(`crm.itemTypes.${row.type}`) }}</Badge></template><template #cell-sku="{ row }"><span class="font-mono text-xs text-ink-muted">{{ row.sku ?? '—' }}</span></template><template #cell-price="{ row }"><span class="tabular font-mono">{{ format.money(row.unitPriceAmount, row.currency) }}</span></template><template #cell-active="{ row }"><Badge :tone="row.active ? 'ok' : 'neutral'" dot>{{ row.active ? t('crm.status.active') : t('crm.sales.catalogue.inactive') }}</Badge></template><template #cell-actions="{ row }"><Button v-if="manage" icon size="sm" variant="ghost" :aria-label="t('crm.sales.catalogue.edit')" @click="edit(row)"><template #icon><Pencil class="size-4" aria-hidden="true" /></template></Button></template><template #empty><EmptyState :title="t('crm.sales.catalogue.empty')"><template #icon><Package /></template></EmptyState></template></DataTable><Pagination :meta="products" /></Card><ProductFormDialog v-if="manage" v-model:open="formOpen" :product="target" :types="types" /></template>
